-- DO NOT apply without owner go-ahead. Dry-run with BEGIN + RAISE EXCEPTION.

BEGIN;

INSERT INTO public.modulos (ordem, titulo, emoji, cor, categoria_id, descricao)
SELECT 21, 'Idade Média', '🏰', '#64748B', 1, 'Mil anos de reinos, mosteiros, cidades, ciência islâmica, universidades, peste e guerras: a Idade Média foi um tempo de mudança intensa — não de escuridão.'
WHERE NOT EXISTS (SELECT 1 FROM public.modulos WHERE titulo = 'Idade Média');

CREATE TEMP TABLE _seed_trail AS
SELECT id AS modulo_id FROM public.modulos WHERE titulo = 'Idade Média';

INSERT INTO public.niveis (modulo_id, ordem, titulo)
SELECT t.modulo_id, v.ordem, v.titulo
FROM _seed_trail t
CROSS JOIN (VALUES
  (1, 'Nível 1 - Após Roma: reinos, Igreja e Carolíngios'),
  (2, 'Nível 2 - Senhorios, castelos e cidades'),
  (3, 'Nível 3 - Islã, Cruzadas e universidades'),
  (4, 'Nível 4 - Crise e transição para o moderno')
) AS v(ordem, titulo)
WHERE NOT EXISTS (
  SELECT 1 FROM public.niveis n WHERE n.modulo_id = t.modulo_id AND n.ordem = v.ordem
);

INSERT INTO public.submodulos (modulo_id, nivel_id, ordem, titulo, data_liberacao_desde_inicio, imagem_url)
SELECT t.modulo_id, n.id, v.ordem, v.titulo, 0, NULL
FROM _seed_trail t
CROSS JOIN (VALUES
  (1, 1, 'Após Roma: reinos bárbaros'),
  (1, 2, 'Igreja, mosteiros e poder'),
  (1, 3, 'Império Carolíngio'),
  (2, 4, 'Feudalismo e senhorio'),
  (2, 5, 'Cavalaria e castelos'),
  (2, 6, 'Cidades e guildas'),
  (3, 7, 'Mundo islâmico medieval'),
  (3, 8, 'Cruzadas e encontros'),
  (3, 9, 'Escolástica e universidades'),
  (4, 10, 'Peste Negra'),
  (4, 11, 'Guerras e revoltas do fim'),
  (4, 12, 'Transição para o moderno')
) AS v(nivel_ordem, ordem, titulo)
JOIN public.niveis n ON n.modulo_id = t.modulo_id AND n.ordem = v.nivel_ordem
WHERE NOT EXISTS (
  SELECT 1 FROM public.submodulos s WHERE s.modulo_id = t.modulo_id AND s.ordem = v.ordem
);

INSERT INTO public.licoes (submodulo_id, ordem, titulo, emoji, conteudo)
SELECT s.id, 1, s.titulo, '🏰',
       jsonb_build_object('preview', v.preview)
FROM _seed_trail t
JOIN public.submodulos s ON s.modulo_id = t.modulo_id
JOIN (VALUES
  (1, 'Depois do século V, o Ocidente se dividiu em reinos governados por elites germânicas: visigodos na Hispânia, francos na Gália, ostrogodos na Itália e vândalos no norte da África. ''Bárbaro'' era um rótulo romano; na prática, esses reis conviveram com populações romanizadas e aproveitaram cidades, latim e parte do direito romano. Clóvis, rei dos francos, aderiu ao cristianismo niceno e firmou aliança com os bispos da Gália. A transição teve violência e perdas, mas também muita continuidade — não foi um apagão da noite para o dia.'),
  (2, 'Com o enfraquecimento do poder imperial, bispos assumiram assistência, mediação e até governo urbano, e o papado ganhou peso em Roma. Mosteiros, como o de Monte Cassino, ligado a Bento de Núrsia, foram centros de oração, trabalho agrícola, hospedagem e cópia de manuscritos. A Igreja era rica e influente, mas não era um bloco único: papas, bispos, abades e reis disputavam poder o tempo todo. Fé e política andavam juntas.'),
  (3, 'Os carolíngios assumiram o poder entre os francos com Pepino, o Breve (751). Carlos Magno ampliou o reino e foi coroado imperador pelo papa Leão III no Natal de 800. O governo dependia de condes, de enviados régios (missi dominici) e de laços de fidelidade pessoal — longe de uma burocracia moderna. A reforma das escolas e da escrita, o chamado Renascimento carolíngio, ajudou a preservar textos antigos; em 843, o Tratado de Verdun dividiu o império entre os netos de Carlos Magno.'),
  (4, '''Feudalismo'' é um conceito historiográfico para descrever relações de fidelidade entre senhores e vassalos ligadas à posse de terras (feudos), sobretudo entre os séculos X e XIII. O senhorio rural, por sua vez, organizava camponeses livres e servos que deviam rendas e trabalho ao senhor. O modelo variou muito entre regiões e épocas: não houve uma pirâmide perfeita e uniforme em toda a Europa, e historiadores ainda debatem o próprio termo.'),
  (5, 'Cavaleiros eram guerreiros de elite a cavalo, cujo ideal combinava prestígio militar, honra e, mais tarde, valores corteses e religiosos. Os primeiros castelos, nos séculos X e XI, muitas vezes eram torres de madeira sobre montes de terra; os de pedra se generalizaram depois. O castelo era residência, fortaleza e centro de poder local — não apenas cenário de torneios. A guerra real foi bem menos romântica do que nos romances de cavalaria.'),
  (6, 'A partir do século XI, o crescimento da população e do comércio reativou antigas cidades e fez surgir outras. Mercadores e artesãos se organizaram em guildas e corporações de ofício, que regulavam qualidade, preços e aprendizado. Muitas cidades obtiveram cartas de franquia e conselhos próprios, negociando autonomia com senhores e reis. Feiras como as de Champagne e redes como a Liga Hanseática conectaram regiões distantes — a Europa medieval estava longe de ser parada.'),
  (7, 'Depois das conquistas do século VII, o califado reuniu povos, línguas e religiões muito diversos; a conversão ao islã foi gradual, ao longo de séculos. Sob os abássidas, Bagdá (fundada em 762) tornou-se um grande polo de comércio e saber. Estudiosos traduziram textos gregos, persas e indianos e produziram obras originais em matemática, medicina, astronomia e óptica. Al-Andalus, na Península Ibérica, foi outro centro de cultura que dialogou com o mundo cristão.'),
  (8, 'As Cruzadas foram expedições militares autorizadas pela Igreja, a partir do Concílio de Clermont (1095). A Primeira tomou Jerusalém em 1099 e criou Estados latinos no Levante; Saladino retomou a cidade em 1187. A Quarta Cruzada saqueou Constantinopla em 1204 — cristãos contra cristãos. Além da guerra, houve comércio, diplomacia e trocas de conhecimento, como nas traduções feitas em Toledo e na Sicília.'),
  (9, 'As universidades surgiram nos séculos XII e XIII como corporações de mestres e estudantes, em cidades como Bolonha, Paris e Oxford. Estudavam-se artes liberais, direito, medicina e teologia. A escolástica usava a lógica e a disputa organizada para tratar de fé e razão; Tomás de Aquino integrou Aristóteles à teologia cristã. Não era um pensamento parado: aquelas discussões formaram hábitos de argumentação que atravessaram a Idade Moderna.'),
  (10, 'A peste, causada pela bactéria Yersinia pestis, chegou à Europa em 1347 por rotas comerciais e matou uma parcela enorme da população até 1351. Cidades portuárias passaram a isolar navios e pessoas, ajudando a consolidar a prática da quarentena. A falta de mão de obra elevou salários em várias regiões e tensionou relações senhoriais. A epidemia também liberou pânico e intolerância: houve massacres de comunidades judaicas em 1348–1349.'),
  (11, 'A Guerra dos Cem Anos entre Inglaterra e França (1337–1453) durou 116 anos, com tréguas e fases distintas, e teve Azincourt, Joana d''Arc e uso crescente de artilharia. Revoltas populares, como a Jacquerie (1358) na França e a Revolta dos Camponeses (1381) na Inglaterra, mostraram tensões sociais depois da peste. Na Inglaterra, a Guerra das Duas Rosas terminou em 1485 com a vitória de Henrique Tudor. Esses conflitos ajudaram a fortalecer monarquias que concentravam impostos e exércitos.'),
  (12, 'Em 1453, os otomanos tomaram Constantinopla; por volta de 1450, Gutenberg aperfeiçoou em Mainz a impressão com tipos móveis metálicos; em 1492, Granada caiu e Colombo cruzou o Atlântico. O Renascimento valorizou o humanismo e a Antiguidade clássica a partir da Itália. A passagem para a Idade Moderna é uma convenção de historiadores, não um corte súbito: muita coisa medieval seguiu viva por séculos.')
) AS v(sub_ordem, preview) ON v.sub_ordem = s.ordem
WHERE NOT EXISTS (SELECT 1 FROM public.licoes l WHERE l.submodulo_id = s.id);

